<?php
if(!defined('ABSPATH'))exit;
class Terttus_Promo_Banner_Widget extends \Elementor\Widget_Base{
 public function get_name(){return 'terttus_promo_banner';} public function get_title(){return 'Terttus Tilbudsbanner';} public function get_icon(){return 'eicon-call-to-action';} public function get_categories(){return ['terttus-widgets'];}
 protected function register_controls(){$this->start_controls_section('c',['label'=>'Indhold']);$this->add_control('eyebrow',['label'=>'Label','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'UGENS TILBUD']);$this->add_control('title',['label'=>'Overskrift','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'Spar på udvalgt smart home']);$this->add_control('text',['label'=>'Tekst','type'=>\Elementor\Controls_Manager::TEXTAREA,'default'=>'Se aktuelle tilbud og gør hjemmet smartere.']);$this->add_control('button',['label'=>'Knap','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'Se tilbud']);$this->add_control('url',['label'=>'Link','type'=>\Elementor\Controls_Manager::URL,'default'=>['url'=>'/shop/?on_sale=1']]);$this->add_control('image',['label'=>'Billede','type'=>\Elementor\Controls_Manager::MEDIA]);$this->end_controls_section();}
 protected function render(){$s=$this->get_settings_for_display();?><section class="tt-promo"><div><small><?php echo esc_html($s['eyebrow']);?></small><h2><?php echo esc_html($s['title']);?></h2><p><?php echo esc_html($s['text']);?></p><a href="<?php echo esc_url($s['url']['url']);?>"><?php echo esc_html($s['button']);?></a></div><?php if(!empty($s['image']['url'])):?><img src="<?php echo esc_url($s['image']['url']);?>" alt=""><?php endif;?></section><style>.tt-promo{display:flex;align-items:center;justify-content:space-between;gap:30px;padding:34px 40px;border-radius:18px;background:#0b5360;color:#fff}.tt-promo h2{color:#fff;margin:5px 0 8px;font-size:clamp(28px,4vw,46px)}.tt-promo small{font-weight:800;letter-spacing:.08em;color:#ff9a5d}.tt-promo p{margin:0 0 20px}.tt-promo a{display:inline-block;background:#ff7b32;color:#fff!important;padding:12px 18px;border-radius:9px;text-decoration:none;font-weight:700}.tt-promo img{max-width:38%;max-height:220px;object-fit:contain}@media(max-width:650px){.tt-promo{padding:26px;flex-direction:column}.tt-promo img{max-width:80%}}</style><?php }
}\Elementor\Plugin::instance()->widgets_manager->register(new Terttus_Promo_Banner_Widget());